#include <random>
#include <functional>

double monte_carlo_mean(std::function<double(double)> f, double a, double b, int n_points, unsigned int& seed) {
    // Initialize random number generator
    std::mt19937 gen(seed);
    std::uniform_real_distribution<double> dis(a, b);
    double sum = 0.0;
    for (int i = 0; i < n_points; ++i) {
        double x = dis(gen);
        sum += f(x);
    }
    // Calculate average function value
    double average = sum / n_points;
    // Estimate integral
    double integral_estimate = average * (b - a);
    return integral_estimate;
}
